using System;
using System.Collections.Generic;
using System.Linq;
using System.Net;
using System.Net.Sockets;
using System.Text;
using TCAdmin.SDK.Hubs.Models.GameQuery;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Myth of Empires answers the Steam (A2S) query on its query port, but it reports its Steam server id as the server
// name and 0 as the player limit (the game's own server list carries the session name). Read A2S_INFO for the
// status, map and player count and report the service's server name and slots instead.
string address = Convert.ToString(Dynamic.Address);
if (string.IsNullOrEmpty(address)) address = ThisService.IPAddress;
int port = ThisService.QueryPort > 0 ? ThisService.QueryPort : ThisService.GamePort;

string ReadString(byte[] data, ref int offset)
{
    int start = offset;
    while (offset < data.Length && data[offset] != 0) offset++;
    var s = Encoding.UTF8.GetString(data, start, offset - start);
    offset++;
    return s;
}

try
{
    byte[] reply;
    using (var udp = new UdpClient())
    {
        udp.Client.ReceiveTimeout = 2500;
        udp.Connect(address, port);
        var request = new List<byte> { 0xFF, 0xFF, 0xFF, 0xFF, 0x54 };
        request.AddRange(Encoding.ASCII.GetBytes("Source Engine Query\0"));
        udp.Send(request.ToArray(), request.Count);
        IPEndPoint from = null;
        reply = udp.Receive(ref from);
        if (reply.Length >= 9 && reply[4] == 0x41) // challenge: repeat the request with it
        {
            request.AddRange(reply.Skip(5).Take(4));
            udp.Send(request.ToArray(), request.Count);
            reply = udp.Receive(ref from);
        }
    }
    if (reply.Length < 6 || reply[4] != 0x49) throw new Exception("Unexpected A2S reply.");
    int o = 6; // header (4) + type (1) + protocol (1)
    ReadString(reply, ref o); // name = the Steam server id
    var map = ReadString(reply, ref o);
    ReadString(reply, ref o); // folder
    ReadString(reply, ref o); // game
    o += 2; // app id
    int players = o < reply.Length ? reply[o] : 0;
    var name = ThisService.Variables.ContainsKey("Hostname") ? Convert.ToString(ThisService.Variables["Hostname"]) : string.Empty;
    Globals.ReturnValue = new GameQueryResponse
    {
        Success = true,
        Status = "online",
        Protocol = "custom_script",
        Address = address,
        Hostname = address + ":" + ThisService.GamePort,
        Name = string.IsNullOrWhiteSpace(name) ? ThisService.Name : name,
        GameType = "MOE",
        Map = map,
        NumPlayers = players,
        MaxPlayers = ThisService.Slots,
        NumSpectators = 0,
        MaxSpectators = 0,
        Retries = 0
    };
}
catch (Exception ex)
{
    Globals.ReturnValue = GameQueryResponse.DefaultOfflineResponse(address, "custom_script", ex.Message);
}

