    {
        var saved = RconCommand(client, "saveworld", 60000);
        ScriptConsole.WriteLine((object)("saveworld: " + (saved.Length > 0 ? saved : "(no reply)")));
        var shutdown = RconCommand(client, "ShutDownServer", 5000);
        ScriptConsole.WriteLine((object)("ShutDownServer: " + (shutdown.Length > 0 ? shutdown : "(no reply)")));
    }
}
catch (Exception ex)
{
