//refAssemblies: TCAdmin.Monitor.SDK.dll, System.Diagnostics.Process.dll
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Linux: makes the native server (LinuxPrivateServer/MOE/Binaries/Linux/MOEServer) executable (Steam downloads lose
// the bit now and then), gives the Steam game server its steamclient.so in ~/.steam/sdk64 (the service root is the
// home directory) and installs missing shared libraries.
var root = (string)ThisService.RootDirectory;
var binaries = Path.Combine(root, "LinuxPrivateServer", "MOE", "Binaries", "Linux");
var server = Path.Combine(binaries, "MOEServer");
if (System.OperatingSystem.IsLinux() && File.Exists(server))
{
    File.SetUnixFileMode(server, File.GetUnixFileMode(server) | UnixFileMode.UserExecute | UnixFileMode.GroupExecute);

    var source = Path.Combine(binaries, "steamclient.so");
    var sdk = Path.Combine(root, ".steam", "sdk64");
    var target = Path.Combine(sdk, "steamclient.so");
    if (File.Exists(source) && (!File.Exists(target) || new FileInfo(target).Length != new FileInfo(source).Length))
    {
        Directory.CreateDirectory(sdk);
        File.Copy(source, target, true);
        GiveToServiceUser(Path.Combine(root, ".steam"), true);
        ScriptConsole.WriteLine((object)"Copied steamclient.so to .steam/sdk64.");
    }
}

// The script runs as the monitor (root): hand what it creates to the service account (root-owned files are hidden in
// the file manager, and the server cannot write them).
void GiveToServiceUser(string path, bool directory)
{
    var credential = ServiceManagerService.GetServiceCredential(ThisService.ServiceId);
    if (directory) Globals.OperatingSystem.SetDirectoryOwner(path, credential.Domain, credential.UserName, true);
    else Globals.OperatingSystem.SetFileOwnerAutoDetect(path);
}

// Linux: install the shared libraries the server binary links but this host does not have.
if (System.OperatingSystem.IsLinux())
{
    var binary = server;
    var packages = new Dictionary<string, (string[] Apt, string[] Rpm)>
    {
        ["libstdc++.so.6"] = (new[] { "libstdc++6" }, new[] { "libstdc++" }),
        ["libgcc_s.so.1"] = (new[] { "libgcc-s1", "libgcc1" }, new[] { "libgcc" }),
        ["libz.so.1"] = (new[] { "zlib1g" }, new[] { "zlib" })
    };
    Shell("ldd '" + binary + "'", out var lddOutput);
    var missing = lddOutput.Split('\n').Where(l => l.Contains("=> not found")).Select(l => l.Trim().Split(' ')[0]).ToList();
    foreach (var soname in missing)
    {
        if (!packages.TryGetValue(soname, out var candidates))
        {
            ScriptConsole.WriteLine((object)("The server needs " + soname + ", which is not installed on this host."));
            continue;
        }
        ScriptConsole.WriteLine((object)(soname + " is missing on this host; installing it."));
        var apt = Shell("command -v apt-get", out _);
        var tool = apt ? "DEBIAN_FRONTEND=noninteractive apt-get install -y " : Shell("command -v dnf", out _) ? "dnf install -y " : "yum install -y ";
        var names = apt ? candidates.Apt : candidates.Rpm;
        var installed = names.Any(p => Shell(tool + p, out _));
        if (!installed && apt && Shell("apt-get update", out _)) installed = names.Any(p => Shell(tool + p, out _));
        if (!installed) throw new Exception(soname + " is missing and could not be installed. Install one of these packages on the host: " + string.Join(", ", names));
        ScriptConsole.WriteLine((object)("Installed " + soname + "."));
    }
}

bool Shell(string command, out string output)
{
    using (var process = Process.Start(new ProcessStartInfo("/bin/sh", new[] { "-c", command }) { RedirectStandardOutput = true, RedirectStandardError = true, UseShellExecute = false }))
    {
        output = process.StandardOutput.ReadToEnd() + process.StandardError.ReadToEnd();
        process.WaitForExit();
        return process.ExitCode == 0;
    }
}
